<script setup lang="ts">
import {ref,computed,onMounted} from 'vue';const emit=defineEmits(['apply']);const genes=ref<any[]>([]),query=ref(''),error=ref('');const visible=computed(()=>genes.value.filter(g=>g.type==='图元'&&g.assets?.some((a:any)=>a.svg)&&(!query.value||(g.name+g.pattern).includes(query.value))).slice(0,24));onMounted(async()=>{try{const r=await fetch('/api/genes');if(!r.ok)throw Error();genes.value=await r.json()}catch{error.value='素材加载失败，请刷新重试'}});function drag(e:DragEvent,g:any){e.dataTransfer?.setData('application/x-xiyu-gene',JSON.stringify({pattern_id:g.pattern,code:g.code}));if(e.dataTransfer)e.dataTransfer.effectAllowed='copy'}
</script>
<template><section class="material-planet"><header><div><small>MATERIAL CONSTELLATION</small><h2>纹样知识星球</h2><p>拖动素材到上方画布，或点击素材应用到点缀层。保留主纹与来源。</p></div><input v-model="query" placeholder="搜索纹样 / PAT 编号" aria-label="搜索星球素材"></header><div class="planet-nodes"><button v-for="g in visible" :key="g.pattern+g.code" draggable="true" @dragstart="drag($event,g)" @click="emit('apply',{pattern_id:g.pattern,code:g.code})"><img :src="g.assets.find((a:any)=>a.svg)?.url" :alt="g.name" loading="lazy"><span>{{g.name}}</span><small>{{g.pattern}} · {{g.status}}</small></button></div><p v-if="!visible.length">{{error||'没有匹配素材，换个关键词试试。'}}</p></section></template>
<style scoped>
.material-planet{margin-top:24px;padding:24px;border:1px solid var(--border-default);border-radius:14px;background:radial-gradient(ellipse at 50% 0,var(--bg-panel),transparent 70%),var(--bg-panel)}.material-planet header{display:flex;justify-content:space-between;gap:20px;align-items:center}.material-planet h2{margin:4px 0;color:var(--text-secondary);font-size:22px}.material-planet p{color:var(--text-secondary);font-size:13px}.material-planet small{color:var(--accent-jade);font-size:11px}.material-planet input{background:var(--bg-panel);color:var(--text-secondary);border:1px solid var(--border-default);padding:10px;border-radius:8px}.planet-nodes{display:grid;grid-template-columns:repeat(auto-fill,minmax(125px,1fr));gap:14px;max-height:340px;overflow:auto;padding:12px 0}.planet-nodes button{background:var(--bg-panel);border:1px solid var(--border-default);border-radius:12px;display:flex;align-items:center;flex-direction:column;padding:12px;gap:8px;color:var(--text-secondary);cursor:grab;transition:transform .2s,border-color .2s}.planet-nodes button:hover{transform:translateY(-3px);border-color:var(--accent-jade)}.planet-nodes img{width:62px;height:62px;object-fit:contain;background:var(--bg-elevated);border-radius:50%;padding:8px}.planet-nodes span{font-size:12px}.planet-nodes small{font-size:10px}@media(max-width:600px){.material-planet{padding:16px}.material-planet header{display:block}.material-planet input{width:100%}}
</style>
